// ====================================================================
// PLAN CLEANUP v2 - STATS housekeeping tiap 3 bulan
// Revisi 2026-08-27: aturan filter dibalik jadi "whitelist baris OFF".
//
// ATURAN BARU
//   HAPUS semua baris data, KECUALI:
//     1. header (baris 1) - tidak pernah disentuh sama sekali
//     2. baris dengan bot_mode == "OFF" yang off_reason-nya BUKAN "VIRA"
//
//   Artinya, dari semua baris yang OFF, satu-satunya yang ikut dihapus
//   adalah yang secara eksplisit dilabeli off_reason = "VIRA" (bot yang
//   mematikan dirinya sendiri atas permintaan user).
//
// KENAPA DIBALIK (aturan lama: hanya off_reason == "SAM" yang disimpan)
//   Label "SAM" harus diisi MANUAL oleh Sam lewat dropdown di sheet.
//   Kalau Sam lupa mengisi - atau dia mematikan bot lewat VIRA Dashboard,
//   yang memang HANYA menulis kolom bot_mode dan tidak pernah menyentuh
//   off_reason - baris itu jadi "OFF tanpa label" dan ikut TERHAPUS.
//   Dengan aturan baru, lupa-label = baris tetap AMAN. Yang hilang hanya
//   yang sudah jelas dilabeli VIRA. Fail-safe, bukan fail-open.
//
// Semua perbandingan case-insensitive + trim, jadi "OFF"/"off"/" Off "
// sama, dan "VIRA"/"vira"/" Vira " juga sama.
//
// STRATEGI AMAN (urutan ini disengaja, JANGAN dibalik):
//   1. salin baris yang dipertahankan ke BAWAH sheet dulu (append)
//   2. baru hapus blok baris asli di atasnya (delete)
// Kalau append gagal -> belum ada yang dihapus -> nol kehilangan data.
// Kalau delete gagal -> cuma duplikat -> masih nol kehilangan data.
// Kalau urutannya dibalik, satu kegagalan append = baris murid Sam
// hilang permanen.
// ====================================================================

const OFF_VALUE    = 'OFF';    // bot_mode yang dilindungi
const DELETE_LABEL = 'VIRA';   // satu-satunya off_reason yang boleh dihapus
const norm = v => String(v ?? '').trim().toUpperCase();

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && typeof r === 'object'
            && r.row_number !== undefined
            && Number(r.row_number) >= 2);

if (!rows.length) {
  console.log('STATS kosong / hanya header - tidak ada yang dibersihkan.');
  return [];
}

// --------------------------------------------------------------
// Guard 1: pastikan yang terbaca benar-benar tab STATS.
// Kalau kolom kuncinya tidak ada, BERHENTI dengan error - lebih baik
// workflow gagal berisik daripada menghapus tab yang salah.
// --------------------------------------------------------------
if (!rows.some(r => 'No WA' in r)) {
  throw new Error('Kolom "No WA" tidak ditemukan - tab yang terbaca kemungkinan bukan STATS. Cleanup DIBATALKAN.');
}

// --------------------------------------------------------------
// Guard 2 (KRITIS di aturan v2): kolom bot_mode wajib ada.
// Di aturan lama, kolom kunci yang mematikan adalah off_reason.
// Di aturan v2, bot_mode-lah yang menentukan baris mana yang selamat -
// kalau kolomnya hilang/berganti nama, SEMUA baris terbaca non-OFF dan
// seluruh isi STATS ikut terhapus. Jadi ini harus hard-fail.
// --------------------------------------------------------------
if (!rows.some(r => 'bot_mode' in r)) {
  throw new Error('Kolom "bot_mode" tidak ditemukan di STATS. Tanpa kolom ini semua baris akan dianggap aktif dan ikut terhapus. Cleanup DIBATALKAN.');
}

// --------------------------------------------------------------
// Guard 3 (peringatan, bukan error): kolom off_reason.
// Di aturan v2 kolom ini hanya dipakai untuk MEMPERSEMPIT apa yang
// dihapus. Kalau kolomnya belum ada, semua baris OFF terbaca tanpa
// label -> semuanya dipertahankan. Itu aman (cuma kurang bersih),
// jadi cukup diberi tanda di laporan WA, tidak perlu membatalkan run.
// --------------------------------------------------------------
const hasOffReason = rows.some(r => 'off_reason' in r);
if (!hasOffReason) {
  console.log('PERINGATAN: kolom "off_reason" belum ada di STATS. Semua baris OFF akan dipertahankan (tidak ada yang dihapus dari kelompok OFF).');
}

const keptRows = [];
let keptOffSam   = 0;   // OFF + off_reason SAM
let keptOffBlank = 0;   // OFF + off_reason kosong (Sam lupa / lewat dashboard)
let keptOffOther = 0;   // OFF + off_reason terisi tapi bukan VIRA/SAM
let delOffVira   = 0;   // OFF + off_reason VIRA  -> dihapus
let delNotOff    = 0;   // bot_mode bukan OFF     -> dihapus

for (const r of rows) {
  const mode   = norm(r.bot_mode);
  const reason = norm(r.off_reason);

  if (mode !== OFF_VALUE) {
    delNotOff++;                       // ON / kosong / apa pun selain OFF
    continue;
  }
  if (reason === DELETE_LABEL) {
    delOffVira++;                      // satu-satunya OFF yang boleh hilang
    continue;
  }

  const copy = { ...r };
  delete copy.row_number;              // kolom bawaan n8n, bukan kolom asli sheet
  keptRows.push(copy);

  if (reason === 'SAM')     keptOffSam++;
  else if (reason === '')   keptOffBlank++;
  else                      keptOffOther++;
}

// Rentang hapus dihitung dari row_number TERBESAR, bukan rows.length,
// supaya baris kosong di tengah (kalau ada) ikut kena hapus dan hasil
// akhirnya rapi tanpa celah.
const maxRow = rows.reduce((m, r) => Math.max(m, Number(r.row_number)), 0);
const totalDataRows = maxRow - 1;

if (totalDataRows < 1) {
  console.log('Tidak ada baris data untuk dibersihkan.');
  return [];
}

const keptCount   = keptRows.length;
const deleteCount = totalDataRows - keptCount;

// Guard 4: kalau tidak ada satu pun baris yang perlu dihapus, JANGAN
// jalankan siklus append+delete. Tanpa ini, seluruh isi sheet disalin
// lalu blok aslinya dihapus - hasil akhirnya sama tapi mengambil risiko
// tulis-hapus besar tanpa manfaat apa pun.
if (deleteCount <= 0) {
  console.log(`Tidak ada baris yang memenuhi syarat hapus (${totalDataRows} baris data, semuanya dipertahankan). Cleanup dilewati.`);
  return [];
}

// Sisa selisih = baris kosong di tengah blok yang ikut terhapus.
const delBlankGap = Math.max(0, deleteCount - delOffVira - delNotOff);

console.log(
  `STATS cleanup v2: ${totalDataRows} baris data | ${keptCount} dipertahankan ` +
  `(SAM ${keptOffSam}, OFF tanpa label ${keptOffBlank}, OFF label lain ${keptOffOther}) | ` +
  `${deleteCount} dihapus (OFF by VIRA ${delOffVira}, bot aktif ${delNotOff}, baris kosong ${delBlankGap}).`
);

return [{
  json: {
    startRow: 2,
    totalDataRows,
    keptCount,
    deleteCount,
    keptOffSam,
    keptOffBlank,
    keptOffOther,
    delOffVira,
    delNotOff,
    delBlankGap,
    hasOffReason,
    keptRows,
  }
}];

// Pecah keptRows jadi item terpisah supaya node Append menulis
// satu baris per item. row_number sudah dibuang di Plan cleanup.
//
// v2: baris yang dipertahankan bukan cuma yang berlabel SAM lagi -
// ini semua baris bot_mode = OFF yang off_reason-nya bukan VIRA.
const plan = $('Plan cleanup').first().json;
const rows = plan.keptRows || [];

if (!rows.length) {
  console.log('Tidak ada baris OFF untuk disalin.');
  return [];
}

console.log(`Menyalin ${rows.length} baris OFF yang dipertahankan ke bawah sebelum blok lama dihapus.`);
return rows.map(r => ({ json: r }));

// Node ini WAJIB mengeluarkan TEPAT 1 item.
// Node Google Sheets jalan sekali per item masuk - kalau node Append
// mengirim 30 item ke sini tanpa diciutkan, node Delete akan jalan
// 30x dan menghapus blok yang salah berkali-kali.
const plan = $('Plan cleanup').first().json;
const last = plan.startRow + plan.totalDataRows - 1;

console.log(`Hapus blok asli: baris ${plan.startRow}..${last} (${plan.totalDataRows} baris). Salinan ${plan.keptCount} baris OFF sudah aman di bawahnya.`);

return [{ json: plan }];
